CNADelimitedBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "CNADelimitedBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "CNA",
                name = "CNADelimited",
                version = c(1,1,0),
                options = options,
                results = CNADelimitedResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Delimited Data (Keywords / Items)
#'
#' 
#' @param data .
#' @param buildModel_variables_field .
#' @param buildModel_variables_by .
#' @param buildModel_sep .
#' @param buildModel_min_occur .
#' @param buildModel_diagonal .
#' @param buildModel_similarity .
#' @param buildModel_edge_threshold .
